def _tile_size(size, cap):
    tile = min(size, cap)
    while size % tile != 0:
        tile -= 1
    return tile


def _diag_kernel(x_ref, diag_ref, max_ref, acc_ref):
    k = pl.program_id(2)
    value = x_ref[0, 0, 0, :][None, :]
    diag_ref[...] = value

    @pl.when(k == 0)
    def _init():
        acc_ref[...] = jnp.full(acc_ref.shape, -jnp.inf, acc_ref.dtype)

    acc_ref[...] = jnp.maximum(acc_ref[...], value)

    @pl.when(k == pl.num_programs(2) - 1)
    def _finish():
        max_ref[...] = acc_ref[...]


def _row_global_kernel(x_ref, row_ref, global_ref, acc_ref):
