    value = x_ref[...]
    row_max = jnp.max(value, axis=1)
    tile_max = jnp.max(row_max, axis=0, keepdims=True)
    row_ref[...] = row_max

    @pl.when(k == 0)
    def _init():
        acc_ref[...] = jnp.full(acc_ref.shape, -jnp.inf, acc_ref.dtype)

    acc_ref[...] = jnp.maximum(acc_ref[...], tile_max)

