import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def _softmax_weights(beta):
    beta = beta.astype(jnp.float32)
    beta = beta - jnp.max(beta, axis=-1, keepdims=True)
    exp_beta = jnp.exp(beta)
    return exp_beta / jnp.sum(exp_beta, axis=-1, keepdims=True)


def _connection_kernel(
    x0_ref,
    x1_ref,
    x2_ref,
    beta0_ref,
    beta1_ref,
    beta2_ref,
    out_ref,
):
    w0 = _softmax_weights(beta0_ref[...])
    w1 = _softmax_weights(beta1_ref[...])
    w2 = _softmax_weights(beta2_ref[...])

    mixed = 3.0 * (
        w0 * x0_ref[...].astype(jnp.float32)
        + w1 * x1_ref[...].astype(jnp.float32)
        + w2 * x2_ref[...].astype(jnp.float32)
    )
    out_ref[...] = jnp.maximum(mixed, 0.0).astype(out_ref.dtype)


def workload(prev_parallel, prev_above, prev_below, betas):
    batch, channels, height, width = prev_parallel.shape

    row_tile = min(16, height)
    while height % row_tile != 0:
        row_tile -= 1

    block_shape = (1, 1, row_tile, width)

    def input_index_map(b, c, h):
        return (b, c, h, 0)

    def beta0_index_map(b, c, h):
        return (0, c, h, 0)

    def beta1_index_map(b, c, h):
        return (1, c, h, 0)

    def beta2_index_map(b, c, h):
        return (2, c, h, 0)

    input_spec = pl.BlockSpec(block_shape, input_index_map)
    output_spec = pl.BlockSpec(block_shape, input_index_map)

    return pl.pallas_call(
        _connection_kernel,
        grid=(batch, channels, height // row_tile),
        in_specs=[
            input_spec,
            input_spec,
            input_spec,
            pl.BlockSpec(block_shape, beta0_index_map),
            pl.BlockSpec(block_shape, beta1_index_map),
            pl.BlockSpec(block_shape, beta2_index_map),
        ],
        out_specs=output_spec,
        out_shape=jax.ShapeDtypeStruct(
            prev_parallel.shape, prev_parallel.dtype
        ),
    )(prev_parallel, prev_above, prev_below, betas, betas, betas)

