import jax
import jax.numpy as jnp
from jax import lax
from jax.experimental import pallas as pl


_STRIDES = (2, 2, 2, 2, 1, 1)
_PAD = 2


def _phase_s2(x_refs, w_ref, row_parity, col_parity, width):
    row_taps = 3 if row_parity == 0 else 2
    col_taps = 3 if col_parity == 0 else 2
    x_parts = []
    w_parts = []
    for i in range(row_taps):
        for j in range(col_taps):
            start = _PAD - j
            x_parts.append(
                x_refs[i][0, 0, start:start + width, :]
            )
            w_parts.append(
                w_ref[2 * i + row_parity, 2 * j + col_parity, :, :]
            )
    lhs = jnp.concatenate(x_parts, axis=1)
    rhs = jnp.concatenate(w_parts, axis=0)
    return lax.dot(lhs, rhs, preferred_element_type=jnp.float32)


def _write_s2_row(x_refs, w_ref, b_ref, o_ref, row_parity):
    out_width = o_ref.shape[2]
    out_channels = o_ref.shape[3]
    odd_width = (out_width - 1) // 2
    even_width = odd_width + 1

    even = _phase_s2(x_refs, w_ref, row_parity, 0, even_width)
    odd = _phase_s2(x_refs, w_ref, row_parity, 1, odd_width)

    pairs = jnp.concatenate(
        (even[:odd_width, None, :], odd[:, None, :]), axis=1
    ).reshape((2 * odd_width, out_channels))
    result = jnp.concatenate(
        (pairs, even[odd_width:odd_width + 1, :]), axis=0
    )
    result = result + b_ref[None, :]
    o_ref[...] = result[None, None, :, :].astype(o_ref.dtype)


def _kernel_s2(x0_ref, x1_ref, x2_ref, w_ref, b_ref, o_ref):
    x_refs = (x0_ref, x1_ref, x2_ref)
    row = pl.program_id(1)

    @pl.when((row & 1) == 0)
    def _even_row():
        _write_s2_row(x_refs, w_ref, b_ref, o_ref, 0)

    @pl.when((row & 1) == 1)
    def _odd_row():
        _write_s2_row(x_refs, w_ref, b_ref, o_ref, 1)


def _kernel_s1(x0_ref, x1_ref, w_ref, b_ref, o_ref):
    x_refs = (x0_ref, x1_ref)
    width = o_ref.shape[2]
    x_parts = []
    w_parts = []
    for i in range(w_ref.shape[0]):
        for j in range(w_ref.shape[1]):
            start = _PAD - j
            x_parts.append(
                x_refs[i][0, 0, start:start + width, :]
            )
            w_parts.append(w_ref[i, j, :, :])

    lhs = jnp.concatenate(x_parts, axis=1)
    rhs = jnp.concatenate(w_parts, axis=0)
    result = lax.dot(lhs, rhs, preferred_element_type=jnp.float32)
    result = result + b_ref[None, :]
    o_ref[...] = result[None, None, :, :].astype(o_ref.dtype)


def _run_layer(x, w, b, stride, out_dtype):
    # x is unpadded NHWC; w is (kernel_h, kernel_w, input, output),
    # using the original, unflipped ConvTranspose2d kernel orientation.
    batch, height, width, in_channels = x.shape
    kernel_h, kernel_w, _, out_channels = w.shape

    padded_channels = in_channels
    if in_channels % 64:
        padded_channels = ((in_channels + 63) // 64) * 64
        x = jnp.pad(
            x,
            ((0, 0), (0, 0), (0, 0),
             (0, padded_channels - in_channels)),
        )
        w = jnp.pad(
            w,
            ((0, 0), (0, 0),
             (0, padded_channels - in_channels), (0, 0)),
        )

    x = jnp.pad(
        x, ((0, 0), (_PAD, _PAD), (_PAD, _PAD), (0, 0))
    )
    out_height = (height - 1) * stride + kernel_h
    out_width = (width - 1) * stride + kernel_w

    def w_map(n, row):
        return (0, 0, 0, 0)

    def b_map(n, row):
        return (0,)

    def o_map(n, row):
        return (n, row, 0, 0)

    if stride == 2:
        def x0_map(n, row):
            return (n, row // 2 + 2, 0, 0)

        def x1_map(n, row):
            return (n, row // 2 + 1, 0, 0)

        def x2_map(n, row):
            return (n, row // 2, 0, 0)

        row_block = (1, 1, x.shape[2], padded_channels)
        in_specs = (
            pl.BlockSpec(row_block, x0_map),
            pl.BlockSpec(row_block, x1_map),
            pl.BlockSpec(row_block, x2_map),
            pl.BlockSpec(w.shape, w_map),
            pl.BlockSpec(b.shape, b_map),
        )
        kernel = _kernel_s2
        args = (x, x, x, w, b)
    else:
        def x0_map(n, row):
            return (n, row + 2, 0, 0)

        def x1_map(n, row):
            return (n, row + 1, 0, 0)

        row_block = (1, 1, x.shape[2], padded_channels)
        in_specs = (
            pl.BlockSpec(row_block, x0_map),
            pl.BlockSpec(row_block, x1_map),
            pl.BlockSpec(w.shape, w_map),
            pl.BlockSpec(b.shape, b_map),
        )
        kernel = _kernel_s1
        args = (x, x, w, b)

    return pl.pallas_call(
        kernel,
        grid=(batch, out_height),
        in_specs=in_specs,
        out_specs=pl.BlockSpec(
            (1, 1, out_width, out_channels), o_map
        ),
        out_shape=jax.ShapeDtypeStruct(
            (batch, out_height, out_width, out_channels), out_dtype
        ),
    )(*args)


def workload(x, *params):
    result = jnp.transpose(x, (0, 2, 3, 1)).astype(jnp.bfloat16)
    layers = len(params) // 2
    for i in range(layers):
        w = jnp.transpose(params[2 * i], (2, 3, 0, 1)).astype(
            jnp.bfloat16
        )
        b = params[2 * i + 1].astype(jnp.float32)
        out_dtype = jnp.float32 if i == layers - 1 else jnp.bfloat16
        result = _run_layer(
            result, w, b, _STRIDES[i], out_dtype
        )
    return jnp.transpose(result, (0, 3, 1, 2))

import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def workload(x, skip):
    batch, x_channels, in_h, in_w = x.shape
    _, skip_channels, out_h, out_w = skip.shape
    total_channels = x_channels + skip_channels

    # A common channel-tile size keeps the upsampled and skip paths in one call.
    block_c = min(128, x_channels, skip_channels)
    while x_channels % block_c != 0 or skip_channels % block_c != 0:
        block_c //= 2
    x_channel_blocks = x_channels // block_c
    channel_blocks = total_channels // block_c

    scale_y = (in_h - 1) / (out_h - 1) if out_h > 1 else 0.0
    scale_x = (in_w - 1) / (out_w - 1) if out_w > 1 else 0.0

    def row_lo_index(y):
        src = y.astype(jnp.float32) * scale_y
        return jnp.minimum(src.astype(jnp.int32), in_h - 1)

    def x_lo_map(n, y, c):
        del n
        return (pl.program_id(0), row_lo_index(y), 0,
                jnp.minimum(c, x_channel_blocks - 1))

    def x_hi_map(n, y, c):
        del n
        return (pl.program_id(0),
                jnp.minimum(row_lo_index(y) + 1, in_h - 1), 0,
                jnp.minimum(c, x_channel_blocks - 1))

    def skip_map(n, y, c):
        return (n, y, 0, jnp.maximum(c - x_channel_blocks, 0))

    def out_map(n, y, c):
        return (n, y, 0, c)

    def kernel(x_lo_ref, x_hi_ref, skip_ref, out_ref):
        y = pl.program_id(1)
        c = pl.program_id(2)

        @pl.when(c < x_channel_blocks)
        def interpolate():
            lo = x_lo_ref[0, 0, :, :]
            hi = x_hi_ref[0, 0, :, :]

            src_y = y.astype(jnp.float32) * scale_y
            i0_y = jnp.minimum(src_y.astype(jnp.int32), in_h - 1)
            frac_y = (src_y - i0_y.astype(jnp.float32)).astype(lo.dtype)
            mixed = lo * (jnp.asarray(1.0, lo.dtype) - frac_y) + hi * frac_y

            # Create the iota in an integer dtype, then convert it to float.
            positions = (
                jnp.arange(out_w, dtype=jnp.int32).astype(jnp.float32) * scale_x
            )
            i0 = jnp.minimum(positions.astype(jnp.int32), in_w - 1)
            i1 = jnp.minimum(i0 + 1, in_w - 1)
            frac = positions - i0.astype(jnp.float32)
            source_columns = jnp.arange(in_w, dtype=jnp.int32)
            mask0 = source_columns[None, :] == i0[:, None]
            mask1 = source_columns[None, :] == i1[:, None]
            weights = (
                jnp.where(mask0, 1.0 - frac[:, None], 0.0)
                + jnp.where(mask1, frac[:, None], 0.0)
            ).astype(mixed.dtype)

            result = jax.lax.dot(
                weights, mixed, preferred_element_type=jnp.float32
            )
            out_ref[0, 0, :, :] = result.astype(out_ref.dtype)

        @pl.when(c >= x_channel_blocks)
        def copy_skip():
            out_ref[...] = skip_ref[...]

    x_nhwc = jnp.transpose(x, (0, 2, 3, 1))
    skip_nhwc = jnp.transpose(skip, (0, 2, 3, 1))

    result_nhwc = pl.pallas_call(
        kernel,
        grid=(batch, out_h, channel_blocks),
        in_specs=[
            pl.BlockSpec((1, 1, in_w, block_c), x_lo_map),
            pl.BlockSpec((1, 1, in_w, block_c), x_hi_map),
            pl.BlockSpec((1, 1, out_w, block_c), skip_map),
        ],
        out_specs=pl.BlockSpec((1, 1, out_w, block_c), out_map),
        out_shape=jax.ShapeDtypeStruct(
            (batch, out_h, out_w, total_channels), x.dtype
        ),
    )(x_nhwc, x_nhwc, skip_nhwc)

    return jnp.transpose(result_nhwc, (0, 3, 1, 2))

