import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def workload(x, skip):
    batch, x_channels, in_h, in_w = x.shape
    _, skip_channels, out_h, out_w = skip.shape
    total_channels = x_channels + skip_channels

    # A common channel-tile size keeps the upsampled and skip paths in one call.
    block_c = min(128, x_channels, skip_channels)
    while x_channels % block_c != 0 or skip_channels % block_c != 0:
        block_c //= 2
    x_channel_blocks = x_channels // block_c
    channel_blocks = total_channels // block_c

    scale_y = (in_h - 1) / (out_h - 1) if out_h > 1 else 0.0
    scale_x = (in_w - 1) / (out_w - 1) if out_w > 1 else 0.0

    def row_lo_index(y):
        src = y.astype(jnp.float32) * scale_y
        return jnp.minimum(src.astype(jnp.int32), in_h - 1)

    def x_lo_map(n, y, c):
        del n
        return (pl.program_id(0), row_lo_index(y), 0,
                jnp.minimum(c, x_channel_blocks - 1))

    def x_hi_map(n, y, c):
        del n
        return (pl.program_id(0),
                jnp.minimum(row_lo_index(y) + 1, in_h - 1), 0,
                jnp.minimum(c, x_channel_blocks - 1))

    def skip_map(n, y, c):
        return (n, y, 0, jnp.maximum(c - x_channel_blocks, 0))

    def out_map(n, y, c):
        return (n, y, 0, c)

    def kernel(x_lo_ref, x_hi_ref, skip_ref, out_ref):
        y = pl.program_id(1)
        c = pl.program_id(2)

        @pl.when(c < x_channel_blocks)
        def interpolate():
            lo = x_lo_ref[0, 0, :, :]
            hi = x_hi_ref[0, 0, :, :]

            src_y = y.astype(jnp.float32) * scale_y
            i0_y = jnp.minimum(src_y.astype(jnp.int32), in_h - 1)
            frac_y = (src_y - i0_y.astype(jnp.float32)).astype(lo.dtype)
            mixed = lo * (jnp.asarray(1.0, lo.dtype) - frac_y) + hi * frac_y

            # Create the iota in an integer dtype, then convert it to float.
            positions = (
                jnp.arange(out_w, dtype=jnp.int32).astype(jnp.float32) * scale_x
            )
            i0 = jnp.minimum(positions.astype(jnp.int32), in_w - 1)
            i1 = jnp.minimum(i0 + 1, in_w - 1)
            frac = positions - i0.astype(jnp.float32)
            source_columns = jnp.arange(in_w, dtype=jnp.int32)
            mask0 = source_columns[None, :] == i0[:, None]
            mask1 = source_columns[None, :] == i1[:, None]
            weights = (
                jnp.where(mask0, 1.0 - frac[:, None], 0.0)
                + jnp.where(mask1, frac[:, None], 0.0)
            ).astype(mixed.dtype)

            result = jax.lax.dot(
                weights, mixed, preferred_element_type=jnp.float32
            )
            out_ref[0, 0, :, :] = result.astype(out_ref.dtype)

        @pl.when(c >= x_channel_blocks)
        def copy_skip():
            out_ref[...] = skip_ref[...]

    x_nhwc = jnp.transpose(x, (0, 2, 3, 1))
    skip_nhwc = jnp.transpose(skip, (0, 2, 3, 1))

    result_nhwc = pl.pallas_call(
        kernel,
        grid=(batch, out_h, channel_blocks),
        in_specs=[
            pl.BlockSpec((1, 1, in_w, block_c), x_lo_map),
            pl.BlockSpec((1, 1, in_w, block_c), x_hi_map),
            pl.BlockSpec((1, 1, out_w, block_c), skip_map),
        ],
        out_specs=pl.BlockSpec((1, 1, out_w, block_c), out_map),
        out_shape=jax.ShapeDtypeStruct(
            (batch, out_h, out_w, total_channels), x.dtype
        ),
    )(x_nhwc, x_nhwc, skip_nhwc)

    return jnp.transpose(result_nhwc, (0, 3, 1, 2))

