import jax
import jax.numpy as jnp
from jax import lax
from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


_HEADS = 4


def _ln_kernel(x_ref, g_ref, b_ref, out_ref):
    x = x_ref[...].astype(jnp.float32)
    mean = jnp.mean(x, axis=-1, keepdims=True)
    centered = x - mean
    var = jnp.mean(centered * centered, axis=-1, keepdims=True)
    y = centered * lax.rsqrt(var + 1e-5)
    y = y * g_ref[...].astype(jnp.float32) + b_ref[...].astype(jnp.float32)
    out_ref[...] = y.astype(out_ref.dtype)


def _layer_norm_rows(x, g, b):
    rows, channels = x.shape
    row_block = 16
    return pl.pallas_call(
        _ln_kernel,
        out_shape=jax.ShapeDtypeStruct(x.shape, jnp.bfloat16),
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(rows // row_block,),
            in_specs=[
                pl.BlockSpec((row_block, channels), lambda i: (i, 0)),
                pl.BlockSpec((channels,), lambda i: (0,)),
                pl.BlockSpec((channels,), lambda i: (0,)),
            ],
            out_specs=pl.BlockSpec((row_block, channels), lambda i: (i, 0)),
        ),
        compiler_params=pltpu.CompilerParams(dimension_semantics=("parallel",)),
    )(x, g, b)


def _kv_kernel(h_ref, wk_ref, wv_ref, k_ref, v_ref, acc_k, acc_v):
    kk = pl.program_id(2)

    @pl.when(kk == 0)
    def _init():
        acc_k[...] = jnp.zeros(acc_k.shape, jnp.float32)
        acc_v[...] = jnp.zeros(acc_v.shape, jnp.float32)

    a = h_ref[...]
    acc_k[...] += jnp.dot(
        a, wk_ref[...], preferred_element_type=jnp.float32
    )
    acc_v[...] += jnp.dot(
        a, wv_ref[...], preferred_element_type=jnp.float32
    )

    @pl.when(kk == pl.num_programs(2) - 1)
    def _store():
        bm = acc_k.shape[0]
        hp = k_ref.shape[1]
        d = k_ref.shape[3]
        k_tile = acc_k[...].reshape(bm, hp, d).transpose(1, 0, 2)
        v_tile = acc_v[...].reshape(bm, hp, d).transpose(1, 0, 2)
        k_ref[...] = k_tile[None, ...].astype(k_ref.dtype)
        v_ref[...] = v_tile[None, ...].astype(v_ref.dtype)


def _project_kv(h, wk, wv, batch, seq_len, heads):
    rows, channels = h.shape
    depth = channels // heads
    bm = 512
    bk = 512
    hp = 2
    bn = hp * depth

    def h_map(i, j, kk):
        del j
        return (i, kk)

    def w_map(i, j, kk):
        del i
        return (kk, j)

    def out_map(i, j, kk):
        del kk
        return (i // (seq_len // bm), j, i % (seq_len // bm), 0)

    out_shape = jax.ShapeDtypeStruct(
        (batch, heads, seq_len, depth), jnp.bfloat16
    )
    return pl.pallas_call(
        _kv_kernel,
        out_shape=(out_shape, out_shape),
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(rows // bm, heads // hp, channels // bk),
            in_specs=[
                pl.BlockSpec((bm, bk), h_map),
                pl.BlockSpec((bk, bn), w_map),
                pl.BlockSpec((bk, bn), w_map),
            ],
            out_specs=(
                pl.BlockSpec((1, hp, bm, depth), out_map),
                pl.BlockSpec((1, hp, bm, depth), out_map),
            ),
            scratch_shapes=[
                pltpu.VMEM((bm, bn), jnp.float32),
                pltpu.VMEM((bm, bn), jnp.float32),
            ],
        ),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel", "arbitrary")
        ),
    )(h, wk, wv)


def _mm_kernel(a_ref, w_ref, out_ref, acc):
    kk = pl.program_id(1)

    @pl.when(kk == 0)
    def _init():
        acc[...] = jnp.zeros(acc.shape, jnp.float32)

    acc[...] += jnp.dot(
        a_ref[...], w_ref[...], preferred_element_type=jnp.float32
    )

    @pl.when(kk == pl.num_programs(1) - 1)
    def _store():
        out_ref[...] = acc[...].astype(out_ref.dtype)


def _mm(a, w):
    rows, inner = a.shape
    cols = w.shape[1]
    bn = 512
    bk = 512

    def a_map(j, kk):
        del j
        return (0, kk)

    return pl.pallas_call(
        _mm_kernel,
        out_shape=jax.ShapeDtypeStruct((rows, cols), jnp.bfloat16),
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(cols // bn, inner // bk),
            in_specs=[
                pl.BlockSpec((rows, bk), a_map),
                pl.BlockSpec((bk, bn), lambda j, kk: (kk, j)),
            ],
            out_specs=pl.BlockSpec((rows, bn), lambda j, kk: (0, j)),
            scratch_shapes=[pltpu.VMEM((rows, bn), jnp.float32)],
        ),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "arbitrary")
        ),
    )(a, w)


def _attention_kernel(q_ref, k_ref, v_ref, out_ref):
    q = q_ref[0, 0, :]
    k = k_ref[0, 0, :, :]
    v = v_ref[0, 0, :, :]
    scores = jnp.dot(
        k, q[:, None], preferred_element_type=jnp.float32
    )[:, 0]
    scores = scores * (q.shape[0] ** -0.5)
    weights = jnp.exp(scores - jnp.max(scores, axis=0))
    weights = weights / jnp.sum(weights, axis=0)
    out = jnp.dot(
        weights.astype(jnp.bfloat16)[None, :],
        v,
        preferred_element_type=jnp.float32,
    )[0, :]
    out_ref[0, 0, :] = out.astype(out_ref.dtype)


def _attention(q, k, v):
    batch, heads, depth = q.shape
    seq_len = k.shape[2]
    spec = pltpu.PrefetchScalarGridSpec(
        num_scalar_prefetch=0,
        grid=(batch, heads),
        in_specs=[
            pl.BlockSpec((1, 1, depth), lambda b, h: (b, h, 0)),
            pl.BlockSpec((1, 1, seq_len, depth), lambda b, h: (b, h, 0, 0)),
            pl.BlockSpec((1, 1, seq_len, depth), lambda b, h: (b, h, 0, 0)),
        ],
        out_specs=pl.BlockSpec((1, 1, depth), lambda b, h: (b, h, 0)),
    )
    return pl.pallas_call(
        _attention_kernel,
        out_shape=jax.ShapeDtypeStruct(q.shape, jnp.bfloat16),
        grid_spec=spec,
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel")
        ),
    )(q, k, v)


def _bias_residual_kernel(a_ref, w_ref, bias_ref, residual_ref, out_ref, acc):
    kk = pl.program_id(1)

    @pl.when(kk == 0)
    def _init():
        acc[...] = jnp.zeros(acc.shape, jnp.float32)

    acc[...] += jnp.dot(
        a_ref[...], w_ref[...], preferred_element_type=jnp.float32
    )

    @pl.when(kk == pl.num_programs(1) - 1)
    def _store():
        value = acc[...] + bias_ref[...].astype(jnp.float32)
        value = value + residual_ref[...].astype(jnp.float32)
        out_ref[...] = value.astype(out_ref.dtype)


def _mm_bias_residual(a, w, bias, residual):
    rows, inner = a.shape
    cols = w.shape[1]
    bn = 512
    bk = 512

    def a_map(j, kk):
        del j
        return (0, kk)

    def out_map(j, kk):
        del kk
        return (0, j)

    return pl.pallas_call(
        _bias_residual_kernel,
        out_shape=jax.ShapeDtypeStruct((rows, cols), jnp.float32),
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(cols // bn, inner // bk),
            in_specs=[
                pl.BlockSpec((rows, bk), a_map),
                pl.BlockSpec((bk, bn), lambda j, kk: (kk, j)),
                pl.BlockSpec((bn,), lambda j, kk: (j,)),
                pl.BlockSpec((rows, bn), out_map),
            ],
            out_specs=pl.BlockSpec((rows, bn), out_map),
            scratch_shapes=[pltpu.VMEM((rows, bn), jnp.float32)],
        ),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "arbitrary")
        ),
    )(a, w, bias, residual)


def _bias_gelu_kernel(a_ref, w_ref, bias_ref, out_ref, acc):
    kk = pl.program_id(1)

    @pl.when(kk == 0)
    def _init():
        acc[...] = jnp.zeros(acc.shape, jnp.float32)

    acc[...] += jnp.dot(
        a_ref[...], w_ref[...], preferred_element_type=jnp.float32
    )

    @pl.when(kk == pl.num_programs(1) - 1)
    def _store():
        value = acc[...] + bias_ref[...].astype(jnp.float32)
        value = jax.nn.gelu(value, approximate=False)
        out_ref[...] = value.astype(out_ref.dtype)


def _mm_bias_gelu(a, w, bias):
    rows, inner = a.shape
    cols = w.shape[1]
    bn = 512
    bk = 512

    def a_map(j, kk):
        del j
        return (0, kk)

    return pl.pallas_call(
        _bias_gelu_kernel,
        out_shape=jax.ShapeDtypeStruct((rows, cols), jnp.bfloat16),
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(cols // bn, inner // bk),
            in_specs=[
                pl.BlockSpec((rows, bk), a_map),
                pl.BlockSpec((bk, bn), lambda j, kk: (kk, j)),
                pl.BlockSpec((bn,), lambda j, kk: (j,)),
            ],
            out_specs=pl.BlockSpec((rows, bn), lambda j, kk: (0, j)),
            scratch_shapes=[pltpu.VMEM((rows, bn), jnp.float32)],
        ),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "arbitrary")
        ),
    )(a, w, bias)


def workload(x, n1g, n1b, wq, wk, wv, wp, bp, n2g, n2b, w1, b1, w2, b2):
    batch, seq_len, channels = x.shape
    heads = _HEADS
    depth = channels // heads
    rows = batch * seq_len

    x_f32 = x.astype(jnp.float32)
    h = _layer_norm_rows(
        x_f32.reshape(rows, channels),
        n1g.astype(jnp.float32),
        n1b.astype(jnp.float32),
    )

    h_cls = h.reshape(batch, seq_len, channels)[:, 0:1, :].reshape(
        batch, channels
    )
    q = _mm(h_cls, wq.astype(jnp.bfloat16)).reshape(batch, heads, depth)
    k, v = _project_kv(
        h,
        wk.astype(jnp.bfloat16),
        wv.astype(jnp.bfloat16),
        batch,
        seq_len,
        heads,
    )

    attended = _attention(q, k, v).reshape(batch, channels)
    x_cls = x_f32[:, 0:1, :].reshape(batch, channels)
    x1 = _mm_bias_residual(
        attended,
        wp.astype(jnp.bfloat16),
        bp.astype(jnp.float32),
        x_cls,
    )

    z = _layer_norm_rows(
        x1, n2g.astype(jnp.float32), n2b.astype(jnp.float32)
    )
    y = _mm_bias_gelu(
        z, w1.astype(jnp.bfloat16), b1.astype(jnp.float32)
    )
    out = _mm_bias_residual(
        y,
        w2.astype(jnp.bfloat16),
        b2.astype(jnp.float32),
        x1,
    )
    return out.reshape(batch, 1, channels)

import jax
import jax.numpy as jnp
from jax import lax
from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


def _batch_tile(n):
    t = min(8, n)
    while n % t:
        t -= 1
    return t


def _reduction_tile(c):
    if c % 128 == 0:
        return 128
    if c % 96 == 0:
        return 96
    t = min(128, c)
    while c % t:
        t -= 1
    return t


def _output_tile(c):
    return 128 if c % 128 == 0 else c


def _dot(x, w):
    return lax.dot_general(
        x,
        w,
        dimension_numbers=(((1,), (0,)), ((), ())),
        preferred_element_type=jnp.float32,
    )


def _accumulate3(xs, w_ref, acc_ref):
    k = pl.program_id(3)

    @pl.when(k == 0)
    def _zero():
        acc_ref[...] = jnp.zeros(acc_ref.shape, dtype=acc_ref.dtype)

    shape = xs[0].shape
    m = shape[0] * shape[2]
    bk = shape[-1]
    acc = acc_ref[...]
    for q, x_ref in enumerate(xs):
        dh, dw = divmod(q, 3)
        lhs = jnp.reshape(x_ref[...], (m, bk))
        rhs = w_ref[dh, dw, :, :]
        acc = acc + _dot(lhs, rhs)
    acc_ref[...] = acc
    return acc


def _accumulate1(x_ref, w_ref, acc_ref):
    k = pl.program_id(3)

    @pl.when(k == 0)
    def _zero():
        acc_ref[...] = jnp.zeros(acc_ref.shape, dtype=acc_ref.dtype)

    shape = x_ref.shape
    m = shape[0] * shape[2]
    bk = shape[-1]
    lhs = jnp.reshape(x_ref[...], (m, bk))
    rhs = w_ref[0, 0, :, :]
    acc = acc_ref[...] + _dot(lhs, rhs)
    acc_ref[...] = acc
    return acc


def _conv3_act_kernel(
    x00, x01, x02, x10, x11, x12, x20, x21, x22,
    w_ref, b_ref, a_ref, o_ref, acc_ref,
):
    acc = _accumulate3(
        (x00, x01, x02, x10, x11, x12, x20, x21, x22),
        w_ref,
        acc_ref,
    )

    @pl.when(pl.program_id(3) == pl.num_programs(3) - 1)
    def _store():
        y = acc + b_ref[...].astype(jnp.float32)
        y = jnp.where(y >= 0, y, a_ref[...].astype(jnp.float32) * y)
        o_ref[...] = jnp.reshape(y, o_ref.shape).astype(o_ref.dtype)


def _conv3_kernel(
    x00, x01, x02, x10, x11, x12, x20, x21, x22,
    w_ref, b_ref, o_ref, acc_ref,
):
    acc = _accumulate3(
        (x00, x01, x02, x10, x11, x12, x20, x21, x22),
        w_ref,
        acc_ref,
    )

    @pl.when(pl.program_id(3) == pl.num_programs(3) - 1)
    def _store():
        y = acc + b_ref[...].astype(jnp.float32)
        o_ref[...] = jnp.reshape(y, o_ref.shape).astype(o_ref.dtype)


def _conv1_act_kernel(x_ref, w_ref, b_ref, a_ref, o_ref, acc_ref):
    acc = _accumulate1(x_ref, w_ref, acc_ref)

    @pl.when(pl.program_id(3) == pl.num_programs(3) - 1)
    def _store():
        y = acc + b_ref[...].astype(jnp.float32)
        y = jnp.where(y >= 0, y, a_ref[...].astype(jnp.float32) * y)
        o_ref[...] = jnp.reshape(y, o_ref.shape).astype(o_ref.dtype)


def _conv1_kernel(x_ref, w_ref, b_ref, o_ref, acc_ref):
    acc = _accumulate1(x_ref, w_ref, acc_ref)

    @pl.when(pl.program_id(3) == pl.num_programs(3) - 1)
    def _store():
        y = acc + b_ref[...].astype(jnp.float32)
        o_ref[...] = jnp.reshape(y, o_ref.shape).astype(o_ref.dtype)


def _conv3(x, w, b, a=None):
    n, h, width, ci = x.shape
    co = w.shape[-1]
    bt = _batch_tile(n)
    bk = _reduction_tile(ci)
    bn = _output_tile(co)
    bm = bt * width
    xp = jnp.pad(x, ((0, 0), (1, 1), (1, 1), (0, 0)))

    in_specs = []
    for dh in range(3):
        for dw in range(3):
            def x_map(nb, row, j, k, dh=dh, dw=dw):
                return (nb, row + dh, dw, k)

            in_specs.append(
                pl.BlockSpec((bt, 1, width, bk), x_map)
            )

    in_specs.append(
        pl.BlockSpec(
            (3, 3, bk, bn),
            lambda nb, row, j, k: (0, 0, k, j),
        )
    )
    in_specs.append(
        pl.BlockSpec((bn,), lambda nb, row, j, k: (j,))
    )

    wb = w.astype(jnp.bfloat16)
    bb = b.astype(jnp.bfloat16)
    args = [xp] * 9 + [wb, bb]
    if a is not None:
        in_specs.append(
            pl.BlockSpec((bn,), lambda nb, row, j, k: (j,))
        )
        args.append(a.astype(jnp.bfloat16))
        kernel = _conv3_act_kernel
    else:
        kernel = _conv3_kernel

    return pl.pallas_call(
        kernel,
        grid=(n // bt, h, co // bn, ci // bk),
        in_specs=in_specs,
        out_specs=pl.BlockSpec(
            (bt, 1, width, bn),
            lambda nb, row, j, k: (nb, row, 0, j),
        ),
        scratch_shapes=[pltpu.VMEM((bm, bn), dtype=jnp.float32)],
        out_shape=jax.ShapeDtypeStruct((n, h, width, co), x.dtype),
    )(*args)


def _conv1(x, w, b, a=None):
    n, h, width, ci = x.shape
    co = w.shape[-1]
    bt = _batch_tile(n)
    bk = _reduction_tile(ci)
    bn = _output_tile(co)
    bm = bt * width

    in_specs = [
        pl.BlockSpec(
            (bt, 1, width, bk),
            lambda nb, row, j, k: (nb, row, 0, k),
        ),
        pl.BlockSpec(
            (1, 1, bk, bn),
            lambda nb, row, j, k: (0, 0, k, j),
        ),
        pl.BlockSpec((bn,), lambda nb, row, j, k: (j,)),
    ]
    args = [x, w.astype(jnp.bfloat16), b.astype(jnp.bfloat16)]
    if a is not None:
        in_specs.append(
            pl.BlockSpec((bn,), lambda nb, row, j, k: (j,))
        )
        args.append(a.astype(jnp.bfloat16))
        kernel = _conv1_act_kernel
    else:
        kernel = _conv1_kernel

    return pl.pallas_call(
        kernel,
        grid=(n // bt, h, co // bn, ci // bk),
        in_specs=in_specs,
        out_specs=pl.BlockSpec(
            (bt, 1, width, bn),
            lambda nb, row, j, k: (nb, row, 0, j),
        ),
        scratch_shapes=[pltpu.VMEM((bm, bn), dtype=jnp.float32)],
        out_shape=jax.ShapeDtypeStruct((n, h, width, co), x.dtype),
    )(*args)


def _concat_kernel(*args):
    o_ref = args[-1]
    offset = 0
    for x_ref in args[:-1]:
        c = x_ref.shape[-1]
        o_ref[0, 0, :, offset:offset + c] = x_ref[0, 0, :, :]
        offset += c


def _concat(*xs):
    n, h, width, _ = xs[0].shape
    total = sum(x.shape[-1] for x in xs)
    in_specs = [
        pl.BlockSpec(
            (1, 1, width, x.shape[-1]),
            lambda nb, row: (nb, row, 0, 0),
        )
        for x in xs
    ]
    return pl.pallas_call(
        _concat_kernel,
        grid=(n, h),
        in_specs=in_specs,
        out_specs=pl.BlockSpec(
            (1, 1, width, total),
            lambda nb, row: (nb, row, 0, 0),
        ),
        out_shape=jax.ShapeDtypeStruct(
            (n, h, width, total), xs[0].dtype
        ),
    )(*xs)


def _stage(x, p):
    i = 0
    n_concat = (len(p) - 5) // 9
    for _ in range(n_concat):
        outs = []
        for _ in range(3):
            x = _conv3(x, p[i], p[i + 1], p[i + 2])
            i += 3
            outs.append(x)
        x = _concat(*outs)
    x = _conv1(x, p[i], p[i + 1], p[i + 2])
    return _conv1(x, p[i + 3], p[i + 4])


def workload(features, l2out, *params):
    split = len(params) // 2
    f = jnp.transpose(features, (0, 2, 3, 1)).astype(jnp.bfloat16)
    l2 = jnp.transpose(l2out, (0, 2, 3, 1)).astype(jnp.bfloat16)
    x = _stage(_concat(f, l2), params[:split])
    x = _concat(f, x, l2)
    out = _stage(x, params[split:])
    return jnp.transpose(out, (0, 3, 1, 2)).astype(features.dtype)

