import jax
import jax.numpy as jnp
from jax import lax
from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


def _batch_tile(n):
    t = min(8, n)
    while n % t:
        t -= 1
    return t


def _reduction_tile(c):
    if c % 128 == 0:
        return 128
    if c % 96 == 0:
        return 96
    t = min(128, c)
    while c % t:
        t -= 1
    return t


def _output_tile(c):
    return 128 if c % 128 == 0 else c


def _dot(x, w):
    return lax.dot_general(
        x,
        w,
        dimension_numbers=(((1,), (0,)), ((), ())),
        preferred_element_type=jnp.float32,
    )


def _accumulate3(xs, w_ref, acc_ref):
    k = pl.program_id(3)

    @pl.when(k == 0)
    def _zero():
        acc_ref[...] = jnp.zeros(acc_ref.shape, dtype=acc_ref.dtype)

    shape = xs[0].shape
    m = shape[0] * shape[2]
    bk = shape[-1]
    acc = acc_ref[...]
    for q, x_ref in enumerate(xs):
        dh, dw = divmod(q, 3)
        lhs = jnp.reshape(x_ref[...], (m, bk))
        rhs = w_ref[dh, dw, :, :]
        acc = acc + _dot(lhs, rhs)
    acc_ref[...] = acc
    return acc


def _accumulate1(x_ref, w_ref, acc_ref):
    k = pl.program_id(3)

    @pl.when(k == 0)
    def _zero():
        acc_ref[...] = jnp.zeros(acc_ref.shape, dtype=acc_ref.dtype)

    shape = x_ref.shape
    m = shape[0] * shape[2]
    bk = shape[-1]
    lhs = jnp.reshape(x_ref[...], (m, bk))
    rhs = w_ref[0, 0, :, :]
    acc = acc_ref[...] + _dot(lhs, rhs)
    acc_ref[...] = acc
    return acc


def _conv3_act_kernel(
    x00, x01, x02, x10, x11, x12, x20, x21, x22,
    w_ref, b_ref, a_ref, o_ref, acc_ref,
):
    acc = _accumulate3(
        (x00, x01, x02, x10, x11, x12, x20, x21, x22),
        w_ref,
        acc_ref,
    )

    @pl.when(pl.program_id(3) == pl.num_programs(3) - 1)
    def _store():
        y = acc + b_ref[...].astype(jnp.float32)
        y = jnp.where(y >= 0, y, a_ref[...].astype(jnp.float32) * y)
        o_ref[...] = jnp.reshape(y, o_ref.shape).astype(o_ref.dtype)


def _conv3_kernel(
    x00, x01, x02, x10, x11, x12, x20, x21, x22,
    w_ref, b_ref, o_ref, acc_ref,
):
    acc = _accumulate3(
        (x00, x01, x02, x10, x11, x12, x20, x21, x22),
        w_ref,
        acc_ref,
    )

    @pl.when(pl.program_id(3) == pl.num_programs(3) - 1)
    def _store():
        y = acc + b_ref[...].astype(jnp.float32)
        o_ref[...] = jnp.reshape(y, o_ref.shape).astype(o_ref.dtype)


def _conv1_act_kernel(x_ref, w_ref, b_ref, a_ref, o_ref, acc_ref):
    acc = _accumulate1(x_ref, w_ref, acc_ref)

    @pl.when(pl.program_id(3) == pl.num_programs(3) - 1)
    def _store():
        y = acc + b_ref[...].astype(jnp.float32)
        y = jnp.where(y >= 0, y, a_ref[...].astype(jnp.float32) * y)
        o_ref[...] = jnp.reshape(y, o_ref.shape).astype(o_ref.dtype)


def _conv1_kernel(x_ref, w_ref, b_ref, o_ref, acc_ref):
    acc = _accumulate1(x_ref, w_ref, acc_ref)

    @pl.when(pl.program_id(3) == pl.num_programs(3) - 1)
    def _store():
        y = acc + b_ref[...].astype(jnp.float32)
        o_ref[...] = jnp.reshape(y, o_ref.shape).astype(o_ref.dtype)


def _conv3(x, w, b, a=None):
    n, h, width, ci = x.shape
    co = w.shape[-1]
    bt = _batch_tile(n)
    bk = _reduction_tile(ci)
    bn = _output_tile(co)
    bm = bt * width
    xp = jnp.pad(x, ((0, 0), (1, 1), (1, 1), (0, 0)))

    in_specs = []
    for dh in range(3):
        for dw in range(3):
            def x_map(nb, row, j, k, dh=dh, dw=dw):
                return (nb, row + dh, dw, k)

            in_specs.append(
                pl.BlockSpec((bt, 1, width, bk), x_map)
            )

    in_specs.append(
        pl.BlockSpec(
            (3, 3, bk, bn),
            lambda nb, row, j, k: (0, 0, k, j),
        )
    )
    in_specs.append(
        pl.BlockSpec((bn,), lambda nb, row, j, k: (j,))
    )

    wb = w.astype(jnp.bfloat16)
    bb = b.astype(jnp.bfloat16)
    args = [xp] * 9 + [wb, bb]
    if a is not None:
        in_specs.append(
            pl.BlockSpec((bn,), lambda nb, row, j, k: (j,))
        )
        args.append(a.astype(jnp.bfloat16))
        kernel = _conv3_act_kernel
    else:
        kernel = _conv3_kernel

    return pl.pallas_call(
        kernel,
        grid=(n // bt, h, co // bn, ci // bk),
        in_specs=in_specs,
        out_specs=pl.BlockSpec(
            (bt, 1, width, bn),
            lambda nb, row, j, k: (nb, row, 0, j),
        ),
        scratch_shapes=[pltpu.VMEM((bm, bn), dtype=jnp.float32)],
        out_shape=jax.ShapeDtypeStruct((n, h, width, co), x.dtype),
    )(*args)


def _conv1(x, w, b, a=None):
    n, h, width, ci = x.shape
    co = w.shape[-1]
    bt = _batch_tile(n)
    bk = _reduction_tile(ci)
    bn = _output_tile(co)
    bm = bt * width

    in_specs = [
        pl.BlockSpec(
            (bt, 1, width, bk),
            lambda nb, row, j, k: (nb, row, 0, k),
        ),
        pl.BlockSpec(
            (1, 1, bk, bn),
            lambda nb, row, j, k: (0, 0, k, j),
        ),
        pl.BlockSpec((bn,), lambda nb, row, j, k: (j,)),
    ]
    args = [x, w.astype(jnp.bfloat16), b.astype(jnp.bfloat16)]
    if a is not None:
        in_specs.append(
            pl.BlockSpec((bn,), lambda nb, row, j, k: (j,))
        )
        args.append(a.astype(jnp.bfloat16))
        kernel = _conv1_act_kernel
    else:
        kernel = _conv1_kernel

    return pl.pallas_call(
        kernel,
        grid=(n // bt, h, co // bn, ci // bk),
        in_specs=in_specs,
        out_specs=pl.BlockSpec(
            (bt, 1, width, bn),
            lambda nb, row, j, k: (nb, row, 0, j),
        ),
        scratch_shapes=[pltpu.VMEM((bm, bn), dtype=jnp.float32)],
        out_shape=jax.ShapeDtypeStruct((n, h, width, co), x.dtype),
    )(*args)


def _concat_kernel(*args):
    o_ref = args[-1]
    offset = 0
    for x_ref in args[:-1]:
        c = x_ref.shape[-1]
        o_ref[0, 0, :, offset:offset + c] = x_ref[0, 0, :, :]
        offset += c


def _concat(*xs):
    n, h, width, _ = xs[0].shape
    total = sum(x.shape[-1] for x in xs)
    in_specs = [
        pl.BlockSpec(
            (1, 1, width, x.shape[-1]),
            lambda nb, row: (nb, row, 0, 0),
        )
        for x in xs
    ]
    return pl.pallas_call(
        _concat_kernel,
        grid=(n, h),
        in_specs=in_specs,
        out_specs=pl.BlockSpec(
            (1, 1, width, total),
            lambda nb, row: (nb, row, 0, 0),
        ),
        out_shape=jax.ShapeDtypeStruct(
            (n, h, width, total), xs[0].dtype
        ),
    )(*xs)


def _stage(x, p):
    i = 0
    n_concat = (len(p) - 5) // 9
    for _ in range(n_concat):
        outs = []
        for _ in range(3):
            x = _conv3(x, p[i], p[i + 1], p[i + 2])
            i += 3
            outs.append(x)
        x = _concat(*outs)
    x = _conv1(x, p[i], p[i + 1], p[i + 2])
    return _conv1(x, p[i + 3], p[i + 4])


def workload(features, l2out, *params):
    split = len(params) // 2
    f = jnp.transpose(features, (0, 2, 3, 1)).astype(jnp.bfloat16)
    l2 = jnp.transpose(l2out, (0, 2, 3, 1)).astype(jnp.bfloat16)
    x = _stage(_concat(f, l2), params[:split])
    x = _concat(f, x, l2)
    out = _stage(x, params[split:])
    return jnp.transpose(out, (0, 3, 1, 2)).astype(features.dtype)

