import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def _gated_activation_kernel(f_ref, gate_ref, out_ref):
    f = f_ref[...]
    gate = gate_ref[...]
    out_ref[...] = jnp.tanh(f) * jax.nn.sigmoid(gate)


def workload(x):
    n, c, h, w = x.shape
    assert c % 2 == 0, "x must have an even number of channels."
    half = c // 2
    spatial = h * w

    row_block = next(
        (b for b in (16, 8, 4, 2, 1) if half % b == 0),
        1,
    )
    spatial_block = next(
        (b for b in (2048, 1024, 512, 256, 128) if spatial % b == 0),
        spatial,
    )

    x_rows = jnp.reshape(x, (n * c, spatial))
    rows_per_batch = c // row_block
    gate_row_offset = half // row_block
    out_rows_per_batch = half // row_block

    def f_index(batch_index, channel_index, spatial_index):
        return (
            batch_index * rows_per_batch + channel_index,
            spatial_index,
        )

    def gate_index(batch_index, channel_index, spatial_index):
        return (
            batch_index * rows_per_batch + gate_row_offset + channel_index,
            spatial_index,
        )

    def out_index(batch_index, channel_index, spatial_index):
        return (
            batch_index * out_rows_per_batch + channel_index,
            spatial_index,
        )

    result = pl.pallas_call(
        _gated_activation_kernel,
        out_shape=jax.ShapeDtypeStruct((n * half, spatial), x.dtype),
        grid=(n, half // row_block, spatial // spatial_block),
        in_specs=[
            pl.BlockSpec((row_block, spatial_block), f_index),
            pl.BlockSpec((row_block, spatial_block), gate_index),
        ],
        out_specs=pl.BlockSpec((row_block, spatial_block), out_index),
    )(x_rows, x_rows)

    return jnp.reshape(result, (n, half, h, w))

