import jax
import jax.numpy as jnp
from jax import lax
from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


def _norm_kernel(x_ref, gamma_ref, beta_ref, out_ref):
    value = x_ref[...]
    mean = jnp.mean(value, axis=(2, 3), keepdims=True)
    centered = value - mean
    var = jnp.mean(jnp.square(centered), axis=(2, 3), keepdims=True)
    value = centered * lax.rsqrt(var + 1e-5)
    gamma = jnp.reshape(gamma_ref[...], (1, gamma_ref.shape[0], 1, 1))
    beta = jnp.reshape(beta_ref[...], (1, beta_ref.shape[0], 1, 1))
    value = jnp.maximum(value * gamma + beta, 0)
    out_ref[0, ...] = jnp.transpose(value[0], (1, 2, 0))


def _conv_kernel(x_ref, w_ref, out_ref, accumulator):
    reduction_index = pl.program_id(4)

    @pl.when(reduction_index == 0)
    def initialize():
        accumulator[...] = jnp.zeros_like(accumulator)

    rows = x_ref.shape[1] * x_ref.shape[2]
    lhs = jnp.reshape(x_ref[0, ...], (rows, x_ref.shape[3]))
    rhs = jnp.reshape(w_ref[...], (w_ref.shape[2], w_ref.shape[3]))
    product = jnp.dot(lhs, rhs, precision=lax.Precision.HIGHEST)
    accumulator[...] += jnp.reshape(product, accumulator.shape)

    @pl.when(reduction_index == pl.num_programs(4) - 1)
    def store():
        result = jnp.transpose(accumulator[...], (2, 0, 1))
        out_ref[0, ...] = result.astype(out_ref.dtype)


def _tile_size(size, candidates):
    for candidate in candidates:
        if size % candidate == 0:
            return candidate
    return 1


def _copy_tile_size(first, second):
    for candidate in (16, 8, 4, 2, 1):
        if first % candidate == 0 and second % candidate == 0:
            return candidate
    return 1


def workload(x, conv_w, gamma, beta):
    batch, channels, height, width = x.shape
    out_channels, input_channels, kernel_h, kernel_w = conv_w.shape

    norm_channels = _tile_size(channels, (16, 8, 4, 2, 1))
    normalized = pl.pallas_call(
        _norm_kernel,
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(batch, channels // norm_channels),
            in_specs=[
                pl.BlockSpec(
                    (1, norm_channels, height, width),
                    lambda n, c: (n, c, 0, 0),
                ),
                pl.BlockSpec(
                    (channels,),
                    lambda n, c: (0,),
                ),
                pl.BlockSpec(
                    (channels,),
                    lambda n, c: (0,),
                ),
            ],
            out_specs=pl.BlockSpec(
                (1, height, width, norm_channels),
                lambda n, c: (n, 0, 0, c),
            ),
        ),
        out_shape=jax.ShapeDtypeStruct(
            (batch, height, width, channels), x.dtype
        ),
    )(x, gamma, beta)

    pad_h = kernel_h // 2
    pad_w = kernel_w // 2
    padded = jnp.pad(
        normalized,
        ((0, 0), (pad_h, pad_h), (pad_w, pad_w), (0, 0)),
    )
    weights = jnp.transpose(conv_w, (2, 3, 1, 0))

    block_h = _tile_size(height, (16, 8, 4, 2, 1))
    block_w = _tile_size(width, (32, 16, 8, 4, 2, 1))
    block_k = _tile_size(input_channels, (128, 64, 32, 16, 8, 4, 2, 1))
    block_o = _tile_size(out_channels, (128, 64, 32, 16, 8, 4, 2, 1))
    k_steps = input_channels // block_k
    reduction_steps = kernel_h * kernel_w * k_steps

    def input_map(n, oh, ow, oc, reduction):
        del oc
        offset = reduction // k_steps
        k = reduction % k_steps
        kh = offset // kernel_w
        kw = offset % kernel_w
        return (n, oh * block_h + kh, ow * block_w + kw, k)

    def weight_map(n, oh, ow, oc, reduction):
        del n, oh, ow
        offset = reduction // k_steps
        k = reduction % k_steps
        kh = offset // kernel_w
        kw = offset % kernel_w
        return (kh, kw, k, oc)

    def conv_output_map(n, oh, ow, oc, reduction):
        del reduction
        return (n, oc, oh, ow)

    convolved = pl.pallas_call(
        _conv_kernel,
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(
                batch,
                height // block_h,
                width // block_w,
                out_channels // block_o,
                reduction_steps,
            ),
            in_specs=[
                pl.BlockSpec(
                    (1, block_h, block_w, block_k),
                    input_map,
                ),
                pl.BlockSpec(
                    (1, 1, block_k, block_o),
                    weight_map,
                ),
            ],
            out_specs=pl.BlockSpec(
                (1, block_o, block_h, block_w),
                conv_output_map,
            ),
            scratch_shapes=[
                pltpu.VMEM((block_h, block_w, block_o), jnp.float32)
            ],
        ),
        out_shape=jax.ShapeDtypeStruct(
            (batch, out_channels, height, width), x.dtype
        ),
    )(padded, weights)

    copy_channels = _copy_tile_size(channels, out_channels)
    input_channel_tiles = channels // copy_channels

    def original_map(n, c):
        return (n, jnp.minimum(c, input_channel_tiles - 1), 0, 0)

    def convolved_map(n, c):
        return (n, jnp.maximum(c - input_channel_tiles, 0), 0, 0)

    def concat_kernel(original_ref, convolved_ref, output_ref):
        channel_tile = pl.program_id(1)

        @pl.when(channel_tile < input_channel_tiles)
        def copy_original():
            output_ref[...] = original_ref[...]

        @pl.when(channel_tile >= input_channel_tiles)
        def copy_convolved():
            output_ref[...] = convolved_ref[...]

    return pl.pallas_call(
        concat_kernel,
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(batch, (channels + out_channels) // copy_channels),
            in_specs=[
                pl.BlockSpec(
                    (1, copy_channels, height, width),
                    original_map,
                ),
                pl.BlockSpec(
                    (1, copy_channels, height, width),
                    convolved_map,
                ),
            ],
            out_specs=pl.BlockSpec(
                (1, copy_channels, height, width),
                lambda n, c: (n, c, 0, 0),
            ),
        ),
        out_shape=jax.ShapeDtypeStruct(
            (batch, channels + out_channels, height, width), x.dtype
        ),
    )(x, convolved)

import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def _partial_std_kernel(x_ref, out_ref):
    a = x_ref[0].astype(jnp.float32)
    b = x_ref[1].astype(jnp.float32)
    c = x_ref[2].astype(jnp.float32)
    d = x_ref[3].astype(jnp.float32)

    total = a + b + c + d
    square_total = a * a + b * b + c * c + d * d
    var = (square_total - 0.25 * total * total) * (1.0 / 3.0)
    var = jnp.maximum(var, 0.0)
    std = jnp.sqrt(var + 1e-8)
    out_ref[...] = jnp.sum(std, dtype=jnp.float32)


def _finish_std_kernel(partials_ref, out_ref, size):
    total = jnp.sum(partials_ref[...], dtype=jnp.float32)
    out_ref[...] = total / jnp.asarray(size, dtype=jnp.float32)


def _emit_kernel(x_ref, std_ref, out_ref, last_channel):
    channel = pl.program_id(1)

    @pl.when(channel == last_channel)
    def _write_std():
        value = std_ref[0].astype(out_ref.dtype)
        out_ref[...] = jnp.broadcast_to(value, out_ref.shape)

    @pl.when(channel != last_channel)
    def _copy_input():
        out_ref[...] = x_ref[...]


def workload(x):
    batch, channels, height, width = x.shape
    spatial = height * width

    grouped = x.reshape(4, -1)
    size = grouped.shape[1]
    block = 16384
    num_blocks = size // block

    partials = pl.pallas_call(
        _partial_std_kernel,
        out_shape=jax.ShapeDtypeStruct((num_blocks, 1), jnp.float32),
        in_specs=[pl.BlockSpec((4, block), lambda i: (0, i))],
        out_specs=pl.BlockSpec((1, 1), lambda i: (i, 0)),
        grid=(num_blocks,),
    )(grouped)

    std = pl.pallas_call(
        lambda partials_ref, out_ref: _finish_std_kernel(
            partials_ref, out_ref, size
        ),
        out_shape=jax.ShapeDtypeStruct((1,), jnp.float32),
        in_specs=[pl.BlockSpec((num_blocks, 1), lambda: (0, 0))],
        out_specs=pl.BlockSpec((1,), lambda: (0,)),
        grid=(),
    )(partials)

    planes = x.reshape(batch, channels, spatial)

    def input_map(b, c):
        return (b, jnp.minimum(c, channels - 1), 0)

    result = pl.pallas_call(
        lambda x_ref, std_ref, out_ref: _emit_kernel(
            x_ref, std_ref, out_ref, channels
        ),
        out_shape=jax.ShapeDtypeStruct(
            (batch, channels + 1, spatial), x.dtype
        ),
        in_specs=[
            pl.BlockSpec((1, 1, spatial), input_map),
            pl.BlockSpec((1,), lambda b, c: (0,)),
        ],
        out_specs=pl.BlockSpec(
            (1, 1, spatial), lambda b, c: (b, c, 0)
        ),
        grid=(batch, channels + 1),
    )(planes, std)

    return result.reshape(batch, channels + 1, height, width)

import jax
import jax.numpy as jnp
from jax import lax
from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


def _conv3(x, w, b, relu, nchw_output):
    n, hp, wp, ci = x.shape
    k, _, _, co = w.shape
    h = hp - 2 * (k // 2)
    width = wp - 2 * (k // 2)

    bh = 8
    bw = 64
    bic = 128 if ci % 128 == 0 else 64
    boc = 256 if co >= 256 else 128
    co_padded = ((co + boc - 1) // boc) * boc

    if co_padded != co:
        w = jnp.pad(w, ((0, 0), (0, 0), (0, 0), (0, co_padded - co)))
        b = jnp.pad(b, (0, co_padded - b.shape[0]))

    out_boc = min(co, boc)
    reductions = (ci // bic) * k * k
    grid = (n, h // bh, width // bw, co_padded // boc, reductions)

    def x_map(batch, oh, ow, _co_tile, r):
        window = r % (k * k)
        return (
            batch,
            oh * bh + window // k,
            ow * bw + window % k,
            (r // (k * k)) * bic,
        )

    def w_map(_batch, _oh, _ow, co_tile, r):
        window = r % (k * k)
        return (window // k, window % k, r // (k * k), co_tile)

    def b_map(_batch, _oh, _ow, co_tile, _r):
        return (co_tile,)

    def out_map(batch, oh, ow, co_tile, _r):
        if nchw_output:
            return (batch, co_tile, oh, ow)
        return (batch, oh, ow, co_tile)

    def kernel(x_ref, w_ref, b_ref, out_ref, acc_ref):
        r = pl.program_id(4)
        xv = jnp.reshape(x_ref[0], (bh * bw, bic))
        wv = jnp.reshape(w_ref[...], (bic, boc))
        partial = lax.dot(
            xv, wv, preferred_element_type=jnp.float32
        ).reshape((1, bh, bw, boc))

        @pl.when(r == 0)
        def initialize():
            acc_ref[...] = partial

        @pl.when(r != 0)
        def accumulate():
            acc_ref[...] = acc_ref[...] + partial

        @pl.when(r == reductions - 1)
        def finish():
            z = acc_ref[...].astype(out_ref.dtype)
            z = z + b_ref[...].reshape((1, 1, 1, boc))
            if relu:
                z = jnp.maximum(z, 0)
            if nchw_output:
                out_ref[0] = jnp.transpose(
                    z[0, :, :, :out_boc], (2, 0, 1)
                )
            else:
                out_ref[...] = z[..., :out_boc]

    if nchw_output:
        output_shape = (n, co, h, width)
        output_block = (1, out_boc, bh, bw)
    else:
        output_shape = (n, h, width, co)
        output_block = (1, bh, bw, out_boc)

    return pl.pallas_call(
        kernel,
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=grid,
            in_specs=[
                pl.BlockSpec((1, bh, bw, bic), x_map),
                pl.BlockSpec((1, 1, bic, boc), w_map),
                pl.BlockSpec((boc,), b_map),
            ],
            out_specs=pl.BlockSpec(output_block, out_map),
            scratch_shapes=[
                pltpu.VMEM((1, bh, bw, boc), dtype=jnp.float32)
            ],
        ),
        out_shape=jax.ShapeDtypeStruct(output_shape, x.dtype),
    )(x, w, b)


def _nearest2(x):
    n, h, w, c = x.shape
    bh = 8
    bw = 32
    bc = 128 if c % 128 == 0 else 64

    def index_map(batch, oh, ow, oc):
        return (batch, oh, ow, oc)

    def kernel(x_ref, out_ref):
        v = x_ref[0]
        v = v[:, None, :, None, :]
        v = jnp.broadcast_to(v, (bh, 2, bw, 2, bc))
        out_ref[0] = jnp.reshape(v, (2 * bh, 2 * bw, bc))

    return pl.pallas_call(
        kernel,
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(n, h // bh, w // bw, c // bc),
            in_specs=[pl.BlockSpec((1, bh, bw, bc), index_map)],
            out_specs=pl.BlockSpec((1, 2 * bh, 2 * bw, bc), index_map),
        ),
        out_shape=jax.ShapeDtypeStruct((n, 2 * h, 2 * w, c), x.dtype),
    )(x)


def workload(y, *params):
    x = jnp.transpose(y, (0, 2, 3, 1))
    layers = len(params) // 2

    for i in range(layers):
        w = params[2 * i]
        b = params[2 * i + 1]
        k = w.shape[2]
        pad = k // 2
        w = jnp.transpose(w, (2, 3, 1, 0))
        x = jnp.pad(
            x,
            ((0, 0), (pad, pad), (pad, pad), (0, 0)),
            mode="reflect",
        )
        is_last = i == layers - 1
        x = _conv3(x, w, b, not is_last, is_last)
        if i in (0, 4, 6):
            x = _nearest2(x)

    return x

