def workload(adj, nodes, w, b):
    batch, in_dim, num_nodes = nodes.shape
    reduction = adj.shape[0]
    out_dim = w.shape[1]

    batch_tile = 1
    n_tile = 1024
    k_tile = 512

    w_t = w.transpose((1, 0))
    bias = b.reshape((1, out_dim, 1))

    def kernel(adj_ref, nodes_ref, w_ref, bias_ref, out_ref, acc_ref):
        x = nodes_ref[...].reshape((batch_tile * in_dim, k_tile))
        partial = jnp.dot(
            x, adj_ref[...], preferred_element_type=jnp.float32
        ).reshape((batch_tile, in_dim, n_tile))

        @pl.when(pl.program_id(2) == 0)
        def initialize_accumulator():
            acc_ref[...] = partial

        @pl.when(pl.program_id(2) != 0)
        def update_accumulator():
            acc_ref[...] += partial

        @pl.when(pl.program_id(2) == pl.num_programs(2) - 1)
        def finish_output_tile():
            h = acc_ref[...].astype(x.dtype)
            h = jnp.where(h >= 0, h, h * 0.2)

            mixed = jnp.einsum(
                "oi,bin->bon",
                w_ref[...],
                h,
                preferred_element_type=jnp.float32,
            )
            result = mixed.astype(h.dtype) + bias_ref[...]
            out_ref[...] = jnp.where(result >= 0, result, result * 0.2)

    return pl.pallas_call(
        kernel,
        out_shape=jax.ShapeDtypeStruct(
            (batch, out_dim, num_nodes), nodes.dtype
        ),
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(
                batch // batch_tile,
                num_nodes // n_tile,
                reduction // k_tile,
            ),
            in_specs=[
                pl.BlockSpec(
                    (k_tile, n_tile), lambda i, j, k: (k, j)
                ),
                pl.BlockSpec(
                    (batch_tile, in_dim, k_tile),
                    lambda i, j, k: (i, 0, k),
                ),
                pl.BlockSpec(
                    (out_dim, in_dim), lambda i, j, k: (0, 0)
                ),
                pl.BlockSpec(
                    (1, out_dim, 1), lambda i, j, k: (0, 0, 0)
                ),
            ],
            out_specs=pl.BlockSpec(
                (batch_tile, out_dim, n_tile),
                lambda i, j, k: (i, 0, j),
            ),
            scratch_shapes=[
                pltpu.VMEM(
                    (batch_tile, in_dim, n_tile), jnp.float32
                )
            ],
        ),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel", "arbitrary")
        ),
    )(adj, nodes, w_t, bias)

