import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def _gem_kernel(x_ref, out_ref):
    v = x_ref[0, 0, :, :].astype(jnp.float32)
    eps = jnp.asarray(1e-6, x_ref.dtype).astype(jnp.float32)
    v = jnp.maximum(v, eps)
    v = v * v * v
    count = v.shape[0] * v.shape[1]
    pooled = jnp.sum(v, dtype=jnp.float32) * (1.0 / count)
    result = jnp.power(pooled, 1.0 / 3.0)
    out_ref[...] = jnp.broadcast_to(result, out_ref.shape).astype(out_ref.dtype)


def workload(x):
    batch, channels, height, width = x.shape

    def input_map(index):
        return (index // channels, index % channels, 0, 0)

    def output_map(index):
        return (index // channels, index % channels, 0, 0)

    return pl.pallas_call(
        _gem_kernel,
        grid=(batch * channels,),
        in_specs=[
            pl.BlockSpec((1, 1, height, width), input_map),
        ],
        out_specs=pl.BlockSpec((1, 1, 1, 1), output_map),
        out_shape=jax.ShapeDtypeStruct(
            (batch, channels, 1, 1), x.dtype
        ),
    )(x)

import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def _avgpool_kernel(x_ref, next_row_ref, out_ref):
    x = x_ref[0, :, :, :]
    next_tile = next_row_ref[0, :, :, :]

    is_last_row = pl.program_id(2) == pl.num_programs(2) - 1
    bottom = jnp.where(is_last_row, x[:, -1:, :], next_tile[:, :1, :])

    below = jnp.concatenate((x[:, 1:, :], bottom), axis=1)
    vertical = x + below

    right = jnp.concatenate(
        (vertical[:, :, 1:], vertical[:, :, -1:]), axis=2
    )
    out_ref[0, :, :, :] = (vertical + right) * 0.25


def workload(x):
    n, c, h, w = x.shape

    if c % 16 == 0:
        block_c = 16
    elif c % 8 == 0:
        block_c = 8
    else:
        block_c = 1

    if h % 16 == 0:
        block_h = 16
    elif h % 8 == 0:
        block_h = 8
    else:
        block_h = h

    row_blocks = h // block_h
    block_shape = (1, block_c, block_h, w)

    def tile_map(ni, ci, hi, wi):
        return ni, ci, hi, wi

    def next_row_map(ni, ci, hi, wi):
        next_hi = jnp.minimum(hi + 1, row_blocks - 1)
        return ni, ci, next_hi, wi

    kernel = pl.pallas_call(
        _avgpool_kernel,
        grid=(n, c // block_c, row_blocks, 1),
        in_specs=[
            pl.BlockSpec(block_shape, tile_map),
            pl.BlockSpec(block_shape, next_row_map),
        ],
        out_specs=pl.BlockSpec(block_shape, tile_map),
        out_shape=jax.ShapeDtypeStruct(x.shape, x.dtype),
    )
    return kernel(x, x)

