    x10_ref, x11_ref, x12_ref,
    x20_ref, x21_ref, x22_ref,
    y_ref,
):
    row0 = jnp.maximum(
        jnp.maximum(x00_ref[...], x01_ref[...]), x02_ref[...]
    )
    row1 = jnp.maximum(
        jnp.maximum(x10_ref[...], x11_ref[...]), x12_ref[...]
    )
    row2 = jnp.maximum(
        jnp.maximum(x20_ref[...], x21_ref[...]), x22_ref[...]
    )
    y_ref[...] = jnp.maximum(jnp.maximum(row0, row1), row2)


