def workload(x):
    batch, channels, height, width = x.shape
    n_chunk = 2
    n_split = 2
    h_step = -(-height // n_split)
    w_step = -(-width // n_chunk)
    n_out = n_chunk * n_split

    def x_map(b, j):
        return (b, 0, j % n_split, j // n_split)

    def out_map(b, j):
        del b, j
        return (0, 0)

    def kernel(x_ref, out_ref):
        b = pl.program_id(0)
        j = pl.program_id(1)

        @pl.when((b == 0) & (j == 0))
        def _initialize():
            out_ref[...] = jnp.zeros_like(out_ref)

        values = x_ref[0, ...]
        pooled = jnp.max(
