        )

        rows = jnp.arange(batch, dtype=jnp.int32)[:, None]
        cols = jnp.arange(n_out, dtype=jnp.int32)[None, :]
        mask = (rows == b) & (cols == j)
        update = jnp.where(
            mask, pooled, jnp.zeros((), dtype=pooled.dtype)
        )
        out_ref[...] = out_ref[...] + update.astype(out_ref.dtype)

    return pl.pallas_call(
        kernel,
        out_shape=jax.ShapeDtypeStruct((batch, n_out), x.dtype),
        grid=(batch, n_out),
        in_specs=[
            pl.BlockSpec((1, channels, h_step, w_step), x_map),
        ],
        out_specs=pl.BlockSpec((batch, n_out), out_map),
    )(x)

